/** Regenerate the app identity from the Home H mark: node tools/gen-app-icons.mjs.
 * PNG/ICO and the React mark work on every host; ICNS generation requires macOS.
 * File-format icons remain separate assets generated by gen-file-association-icons.mjs.
 */
import { execFileSync } from 'node:child_process'
import { copyFileSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { chromium } from 'playwright'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const build = join(root, 'apps/shell/build')
const svg = readFileSync(join(build, 'icon.svg'), 'utf8')
const mark = svg.slice(svg.indexOf('>') + 1, svg.lastIndexOf('</svg>')).trim()
const inverse = mark.replace(/#ffffff|#000000/g, (color) =>
  color === '#ffffff' ? '#000000' : '#ffffff',
)
writeFileSync(
  join(root, 'apps/shell/src/renderer/src/assets/hermesoffice-logo.svg'),
  `<svg width="1096" height="240" viewBox="0 0 1096 240" fill="none" xmlns="http://www.w3.org/2000/svg">\n${inverse}\n` +
    '<text x="330" y="160" font-family="-apple-system, BlinkMacSystemFont, Segoe UI, Roboto, Helvetica, Arial, sans-serif" font-size="116" font-weight="700" fill="#1a1a1a" letter-spacing="-2">HermesOffice</text>\n</svg>\n',
)
const jsx = mark
  .replace(/stroke-width=/g, 'strokeWidth=')
  .replace(/stroke-linecap=/g, 'strokeLinecap=')
writeFileSync(
  join(root, 'packages/ui/src/hermes-mark.tsx'),
  '/** Generated from apps/shell/build/icon.svg by tools/gen-app-icons.mjs. */\n' +
    'export function HermesMark({ size = 26 }: { readonly size?: number }) {\n' +
    '  return (<svg width={size} height={size} viewBox="0 0 240 240" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" data-hermesoffice-mark="monochrome">\n' +
    jsx +
    '\n</svg>)\n}\n',
)

function ico(entries) {
  const header = Buffer.alloc(6)
  header.writeUInt16LE(1, 2)
  header.writeUInt16LE(entries.length, 4)
  const directory = Buffer.alloc(entries.length * 16)
  let offset = 6 + directory.length
  entries.forEach(({ size, png }, index) => {
    const at = index * 16
    directory.writeUInt8(size === 256 ? 0 : size, at)
    directory.writeUInt8(size === 256 ? 0 : size, at + 1)
    directory.writeUInt16LE(1, at + 4)
    directory.writeUInt16LE(32, at + 6)
    directory.writeUInt32LE(png.length, at + 8)
    directory.writeUInt32LE(offset, at + 12)
    offset += png.length
  })
  return Buffer.concat([header, directory, ...entries.map(({ png }) => png)])
}

execFileSync(process.execPath, [
  join(root, 'node_modules/prettier/bin/prettier.cjs'),
  '--write',
  join(root, 'packages/ui/src/hermes-mark.tsx'),
])

const browser = await chromium.launch({ channel: 'chrome', headless: true })
const temporary = mkdtempSync(join(tmpdir(), 'hermesoffice-app-icons-'))
try {
  const page = await browser.newPage({ deviceScaleFactor: 1 })
  const url = `data:image/svg+xml;base64,${Buffer.from(svg).toString('base64')}`
  const render = async (size, ratio = 1) => {
    await page.setViewportSize({ width: size, height: size })
    await page.setContent(
      `<body style="margin:0;background:transparent"><img src="${url}" style="position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:${size * ratio}px;height:${size * ratio}px"></body>`,
    )
    await page.locator('img').evaluate((image) => image.decode())
    return page.screenshot({ omitBackground: true })
  }
  const full = await render(1024)
  const mac = await render(1024, 824 / 1024)
  writeFileSync(join(build, 'icon.png'), full)
  writeFileSync(join(build, 'icon-mac.png'), mac)
  const linux = join(build, 'icons')
  mkdirSync(linux, { recursive: true })
  for (const size of [16, 32, 48, 64, 128, 256, 512, 1024])
    writeFileSync(join(linux, `${size}x${size}.png`), await render(size))
  const entries = []
  for (const size of [16, 24, 32, 48, 64, 128, 256]) entries.push({ size, png: await render(size) })
  writeFileSync(join(build, 'icon.ico'), ico(entries))
  if (process.platform === 'darwin') {
    const iconset = join(temporary, 'app.iconset')
    mkdirSync(iconset)
    for (const base of [16, 32, 128, 256, 512]) {
      writeFileSync(join(iconset, `icon_${base}x${base}.png`), await render(base, 824 / 1024))
      writeFileSync(
        join(iconset, `icon_${base}x${base}@2x.png`),
        await render(base * 2, 824 / 1024),
      )
    }
    execFileSync('iconutil', ['-c', 'icns', iconset, '-o', join(build, 'icon.icns')])
  }
  for (const app of ['docs', 'sheets', 'slides'])
    writeFileSync(join(root, `apps/${app}/src/renderer/assets/app-icon.png`), full)
  writeFileSync(join(root, 'apps/shell/src/renderer/src/assets/app-icon.png'), full)
  for (const name of [
    'icon.png',
    'icon-mac.png',
    'icon.ico',
    ...(process.platform === 'darwin' ? ['icon.icns'] : []),
  ])
    copyFileSync(join(build, name), join(root, 'apps/docs/build', name))
  console.log('Generated the shared Home mark, renderer assets, and macOS/Windows/Linux app icons.')
} finally {
  await browser.close()
  rmSync(temporary, { recursive: true, force: true })
}
